// Generated by build_site.py from data/glossary.csv and data/abbreviations.csv: popup text for terms.
window.SF_TERMS = {"katepisternum":{"t":"Katepisternum","f":"","s":"mesokatepisternum","x":"both","d":"Lower lateral thoracic sclerite below the katepisternal sulcus. Haired in <i>Simulium</i> (<i>Gomphostilbia</i>), bare in <i>Daviesellum</i>, <i>Nevermannia</i>, <i>Asiosimulium</i> and <i>Simulium</i> s.str. (Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#katepisternum"},"sensory-vesicle":{"t":"Sensory vesicle","f":"","s":"Lutz&#x27;s organ","x":"both","d":"Internal sensory organ inside the 3rd maxillary palpal segment; its relative length compared with the 3rd segment (e.g. 0.3 vs 0.5-0.7x) is a major diagnostic character in females (Takaoka &amp; Choochote 2004).","g":"glossary.html#sensory-vesicle"},"cibarium":{"t":"Cibarium","f":"","s":"buccopharyngeal armature","x":"female","d":"Internal feeding pump sclerite of the female head; its posterior margin may be smooth, bear a smooth or tuberculate medial projection (many <i>Simulium</i> s.str.), or carry ca. 100-120 spinous processes in <i>Asiosimulium</i> (Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#cibarium"},"genital-fork":{"t":"Genital fork","f":"","s":"sternite 9","x":"female","d":"Inverted-Y-shaped internal sclerite of the female terminalia with a median stem and paired lateral arms, which may bear anteriorly or anterodorsally directed projections (Takaoka &amp; Kuvangkadilok 1999; Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#genital-fork"},"ovipositor-valve":{"t":"Ovipositor valve","f":"","s":"anterior gonapophysis; hypogynial valve","x":"female","d":"Paired membranous ventral lobes arising from posterior margin of female sternite 8 (termed anterior gonapophyses in Takaoka &amp; Kuvangkadilok 1999 and Kuvangkadilok &amp; Takaoka 2000; ovipositor valves in Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#ovipositor-valve"},"paraproct":{"t":"Paraproct","f":"","s":"","x":"female","d":"Paired sclerotized plates ventral to the cerci in female terminalia; bears a cluster of dark spines in <i>Daviesellum</i> and lacks dark spines in <i>Simulium</i> s.str. (Takaoka &amp; Choochote 2004).","g":"glossary.html#paraproct"},"spermatheca":{"t":"Spermatheca","f":"","s":"","x":"female","d":"Sclerotized sperm-storage capsule of the female; normally single in Simuliidae (with two short accessory ducts), uniquely three (one principal plus two accessory capsules) in <i>S. triglobus</i> (Takaoka &amp; Kuvangkadilok 1999).","g":"glossary.html#spermatheca"},"coxite":{"t":"Coxite","f":"","s":"gonocoxite","x":"male","d":"Basal segment of the male clasper (gonopod); longer than the style in <i>Nevermannia</i> and <i>Asiosimulium</i>, shorter than the style in <i>Daviesellum</i> and <i>Simulium</i> s.str. (Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#coxite"},"style":{"t":"Style","f":"","s":"gonostylus","x":"male","d":"Distal articulated segment of the male clasper bearing an apical or subterminal spine and in some <i>Simulium</i> s.str. (e.g. multistriatum group) a spinose basal protuberance (Takaoka &amp; Kuvangkadilok 1999; Takaoka &amp; Choochote 2004).","g":"glossary.html#style"},"ventral-plate":{"t":"Ventral plate","f":"","s":"","x":"male","d":"Median ventral sclerite of the male genitalia with anterior basal arms; its shape (transverse, lamellate, subquadrate, or narrowed) and posterior teeth are diagnostic (Takaoka &amp; Kuvangkadilok 1999; Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#ventral-plate"},"paramere":{"t":"Paramere","f":"","s":"","x":"male","d":"Paired internal sclerites of the male genitalia typically bearing one or more parameral hooks (e.g. 1 hook in vernum group, 3-4 in feuerborni group), or lacking hooks in <i>Asiosimulium</i> (Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#paramere"},"calcipala":{"t":"Calcipala","f":"","s":"","x":"both","d":"Flattened apical lobe on the inner posterior margin of the hind basitarsus; well developed in <i>Simulium</i> s.l. (Takaoka &amp; Choochote 2005).","g":"glossary.html#calcipala"},"pedisulcus":{"t":"Pedisulcus","f":"","s":"","x":"both","d":"Deep dorsal notch on the 2nd hind tarsal segment; well developed in <i>Simulium</i> s.l. (Takaoka &amp; Choochote 2005).","g":"glossary.html#pedisulcus"},"grapnel-like-hooklets":{"t":"Grapnel-like hooklets","f":"","s":"","x":"pupa","d":"Anchor-shaped multiple-pronged hooklets on each side of the last (9th) abdominal segment of the pupa, diagnostic of subgenus <i>Gomphostilbia</i> in Thailand (Kuvangkadilok &amp; Takaoka 2000; Takaoka &amp; Choochote 2004).","g":"glossary.html#grapnel-like-hooklets"},"spine-combs":{"t":"Spine-combs","f":"","s":"","x":"pupa","d":"Transverse rows of backward-directed spines on the dorsal surface of posterior pupal abdominal segments (typically segments 6-9 or 7-9); absent on segments 5-9 in <i>Asiosimulium</i> (Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#spine-combs"},"terminal-hooks":{"t":"Terminal hooks","f":"","s":"","x":"pupa","d":"Pair of dorsal conical or hook-like sclerotized projections on the last abdominal segment (tergum 9) of the pupa; their presence, absence, or serrate/undulate outer margin separates species (Takaoka &amp; Choochote 2004).","g":"glossary.html#terminal-hooks"},"hypostomium":{"t":"Hypostomium","f":"","s":"hypostoma","x":"larva","d":"Sclerotized anteroventral plate of the larval head capsule bearing an apical row of teeth (13 in <i>Daviesellum</i>, 9 in other Thai subgenera), lateral serrations and paired hypostomal bristles (Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#hypostomium"},"postgenal-cleft":{"t":"Postgenal cleft","f":"","s":"ventral cleft","x":"larva","d":"Unsclerotized indentation on the ventral posterior margin of the larval head capsule behind the postgenal bridge; vestigial in <i>Montisimulium</i>, deep and variably shaped in other subgenera (Takaoka &amp; Choochote 2004).","g":"glossary.html#postgenal-cleft"},"ventral-papillae":{"t":"Ventral papillae","f":"","s":"","x":"larva","d":"Paired conical fleshy protuberances on the ventral surface of the last larval abdominal segment; large in <i>Gomphostilbia</i>, <i>Nevermannia</i> and <i>Montisimulium</i>, absent or very small in <i>Simulium</i> s.str. and <i>Asiosimulium</i> (Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#ventral-papillae"},"accessory-sclerite":{"t":"Accessory sclerite","f":"","s":"","x":"larva","d":"Additional sclerotized plate ventrolateral or ventral on the last larval abdominal segment beside the anal sclerite; present in <i>S. nigrogilvum</i> and <i>S. caudisclerum</i> (Takaoka &amp; Choochote 2004).","g":"glossary.html#accessory-sclerite"},"posterior-circlet":{"t":"Posterior circlet","f":"","s":"","x":"larva","d":"Terminal ring of concentric rows of minute hooklets used by the larva to attach to silk pads on stream substrates; row and hooklet counts aid species identification (Takaoka &amp; Kuvangkadilok 1999; Takaoka &amp; Choochote 2004).","g":"glossary.html#posterior-circlet"},"rectal-organ":{"t":"Rectal organ","f":"","s":"rectal gill","x":"larva","d":"Eversible trilobed osmoregulatory organ of the larva, simple or compound with finger-like secondary lobules per lobe (termed rectal gill in Takaoka &amp; Kuvangkadilok 1999 and Kuvangkadilok &amp; Takaoka 2000; rectal organ in Takaoka &amp; Choochote 2004, 2005).","g":"glossary.html#rectal-organ"},"interspiracular-trunk":{"t":"Interspiracular trunk","f":"","s":"","x":"pupa","d":"Short basal stem connecting the pupal spiracle to the common basal stalk of the pupal gill; its length and thickness relative to the common basal stalk and filament stalks are key diagnostic ratios in <i>Gomphostilbia</i> (Takaoka et al. 2020).","g":"glossary.html#interspiracular-trunk"},"basal-fenestra":{"t":"Basal fenestra","f":"","s":"","x":"pupa","d":"Transparent membranous window or swelling at the base of the pupal gill (and visible in the mature larval gill histoblast); normal and small in most <i>Asiosimulium</i>, extremely bulbous in <i>S. suchitrae</i> (Srisuka et al. 2024).","g":"glossary.html#basal-fenestra"},"median-sclerite":{"t":"Median sclerite","f":"","s":"medial sclerite","x":"male","d":"Thin plate-like internal sclerite arising near the anterior margin of the male ventral plate and directed dorsally; broadened, rounded with sutures and upturned apically in <i>S. kittipati</i> (Srisuka et al. 2024).","g":"glossary.html#median-sclerite"},"frons-head-ratio":{"t":"Frons:head ratio","f":"","s":"frons-head ratio","x":"female","d":"Ratio of the greatest width of the female frons (normalized to 1.0) to the greatest width of the head, used to separate closely related females in <i>Gomphostilbia</i> (Takaoka et al. 2020; Srisuka et al. 2022).","g":"glossary.html#frons-head-ratio"},"upper-eye-facets":{"t":"Upper-eye facets","f":"","s":"upper-eye (large) facets","x":"male","d":"Enlarged ommatidia occupying the upper half of the holoptic male compound eye; their colour (vermilion vs brown) and counts of vertical columns and horizontal rows are primary diagnostic characters in male <i>Simulium</i> keys (Takaoka et al. 2020; Srisuka et al. 2024).","g":"glossary.html#upper-eye-facets"},"postgenal-bridge":{"t":"Postgenal bridge","f":"","s":"","x":"larva","d":"Sclerotized ventral strip of the larval head capsule separating the anterior apex of the postgenal cleft from the posterior margin of the hypostoma; the cleft-to-bridge length ratio is widely used in larval keys (Takaoka et al. 2020; Srisuka et al. 2024).","g":"glossary.html#postgenal-bridge"},"subesophageal-ganglion":{"t":"Subesophageal ganglion","f":"","s":"","x":"larva","d":"Ventral nerve ganglion visible through the larval postgenal cleft; its sheath is dark-pigmented in <i>S. furvum</i>, <i>S. kittipati</i>, <i>S. phurueaense</i> and <i>S. khongchiamense</i> and unpigmented in <i>S. oblongum</i>, <i>S. saeungae</i> and <i>S. wanchaii</i> (Srisuka et al. 2024).","g":"glossary.html#subesophageal-ganglion"},"histoblast":{"t":"Histoblast","f":"","s":"gill histoblast; pharate pupal gill","x":"larva","d":"Darkened coiled developing pupal gill visible laterally on the thorax of mature (final-instar) larvae; dissected to count filament numbers, basal stalk length and basal fenestra shape (Takaoka et al. 2020; Srisuka et al. 2024).","g":"glossary.html#histoblast"},"labral-fan":{"t":"Labral fan","f":"","s":"cephalic fan","x":"larva","d":"Paired filtering fans on the larval head bearing countable primary (main) rays with rows of microtrichia; primary ray counts separate species in <i>Asiosimulium</i> and <i>Gomphostilbia</i> (Takaoka et al. 2020; Srisuka et al. 2024).","g":"glossary.html#labral-fan"},"antenna":{"t":"Antenna","f":"","s":"antennomeres; flagellomeres","x":"both","d":"Segmented sensory appendage of the adult head composed of scape, pedicel and nine flagellomeres (11 segments total in <i>Simulium</i>, 10 or 11 in <i>Austrosimulium</i>); segment counts and coloration of basal versus apical flagellomeres are diagnostic in adult keys (Dumbleton 1963; Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#antenna"},"maxillary-palpus":{"t":"Maxillary palpus","f":"","s":"maxillary palp; palpomeres","x":"both","d":"Five-segmented sensory appendage of the adult mouthparts; relative lengths of the third, fourth and fifth segments and the size of the sensory vesicle in the third segment are widely used in adult keys (Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#maxillary-palpus"},"lacinia":{"t":"Lacinia","f":"","s":"maxillary lacinia","x":"female","d":"Blade-like cutting lobe of the female maxilla bearing countable rows of inner and outer teeth (e.g. 15–16 inner and 13 outer teeth in <i>S. kittipati</i>; 12 inner and 14–15 outer teeth in <i>S. mirum</i>) (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#lacinia"},"mandible":{"t":"Mandible","f":"","s":"","x":"both","d":"Toothed cutting mouthpart of the female (with countable inner and outer teeth, or toothed on one vs both sides of apex in <i>Austrosimulium</i>) and chewing mouthpart of the larva bearing apical comb-teeth and mandibular serrations (Dumbleton 1963; Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#mandible"},"scutum":{"t":"Scutum","f":"","s":"mesonotum","x":"both","d":"Large convex dorsal plate of the adult thorax; its colour, hair vestiture, pruinosity, iridescence, and longitudinal vittae or paired nonpruinose spots are key diagnostic characters in female and male keys (Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#scutum"},"scutellum":{"t":"Scutellum","f":"","s":"","x":"both","d":"Posterior dorsal sclerite of the adult thorax immediately behind the scutum; bears upright long and short hairs (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#scutellum"},"tibia":{"t":"Tibia","f":"","s":"hind tibia; fore tibia; mid tibia","x":"both","d":"Fourth leg segment between femur and tarsus; coloration, pale basal/medial bands, iridescence and spindle-shaped dilation of the hind tibia separate adult species (Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#tibia"},"basitarsus":{"t":"Basitarsus","f":"","s":"fore basitarsus; hind basitarsus; first tarsomere","x":"both","d":"First (basal) tarsal segment of the leg; inflation and dorsal hair crest of the fore basitarsus and parallel-sided versus spindle-shaped enlargement and colour banding of the hind basitarsus are primary adult key characters (Takaoka et al. 2016, 2019, 2020; Srisuka et al. 2024).","g":"glossary.html#basitarsus"},"claw":{"t":"Claw","f":"","s":"tarsal claw","x":"female","d":"Paired terminal claws on the female tarsus; simple or armed with a small subbasal tooth or large basal tooth (e.g. 0.40x claw length in <i>S. kittipati</i>), a key character separating species and host-feeding groups (Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#claw"},"subcosta":{"t":"Subcosta","f":"","s":"subcostal vein","x":"both","d":"Longitudinal wing vein running behind the costa; whether the subcosta is haired or bare ventrally separates females in <i>Simulium</i> s.str. and the <i>S. varicorne</i> species-group (Takaoka et al. 2016, 2019; Srisuka et al. 2022, 2024).","g":"glossary.html#subcosta"},"radial-vein":{"t":"Radial vein","f":"","s":"radius; vein R","x":"both","d":"Major anterior longitudinal wing vein; hairing of the basal section of the radius, colour of the hair tuft at the base of the radial vein, and spinules on R1 separate subgenera and species (Takaoka &amp; Choochote 2004; Takaoka et al. 2016, 2019, 2020; Srisuka et al. 2024).","g":"glossary.html#radial-vein"},"abdominal-tergites":{"t":"Abdominal tergites","f":"","s":"tergites; sternites; basal scale","x":"both","d":"Dorsal plates (tergites) and ventral plates (sternites) of the adult abdomen; shiny dorsolateral spots on tergites 2 and 5–8, basal scale hair fringe, and sternal plate on segment 7 are used in adult keys (Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#abdominal-tergites"},"sternite-8":{"t":"Sternite 8","f":"","s":"eighth sternite","x":"female","d":"Ventral sclerite of the eighth abdominal segment of the female, anterior to the ovipositor valves; typically bare medially and bearing countable lateral hairs on each side (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#sternite-8"},"cercus":{"t":"Cercus","f":"","s":"cerci","x":"both","d":"Paired terminal lobes at the apex of the adult abdomen, dorsal to the paraprocts in females (greatly elongated in <i>Asiosimulium</i>, 1.6–2.0x basal width) and rounded or narrow beside the tenth abdominal segment in males (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#cercus"},"aedeagal-membrane":{"t":"Aedeagal membrane","f":"","s":"","x":"male","d":"Membranous lobe posterior to the male ventral plate covered with minute setae and supporting the dorsal plate (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#aedeagal-membrane"},"dorsal-plate":{"t":"Dorsal plate","f":"","s":"","x":"male","d":"Sclerotized plate on the dorsal surface of the male aedeagal membrane, square and lightly pigmented in <i>S. kittipati</i> or short and sclerotized in <i>S. mirum</i> (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#dorsal-plate"},"pupal-gill":{"t":"Pupal gill","f":"","s":"gill filaments; respiratory organ","x":"pupa","d":"Paired thoracic respiratory organs of the pupa composed of slender filaments (e.g. 2, 4, 6, 8, or arborescent 18–56 filaments in <i>Asiosimulium</i>) arising from a common basal stalk; filament count, branching arrangement, thickness and annular ridges are the primary pupal key characters (Takaoka et al. 2016, 2019, 2020; Srisuka et al. 2024).","g":"glossary.html#pupal-gill"},"cocoon":{"t":"Cocoon","f":"","s":"","x":"pupa","d":"Woven silk case enclosing the pupa on stream substrates; wall-pocket (slipper-shaped) or shoe-shaped with an anterior collar, sometimes with an anterodorsal projection or lateral fenestrae, and thickly or thinly woven (Takaoka &amp; Choochote 2004; Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#cocoon"},"pupal-frons-tubercles":{"t":"Pupal frons &amp; tubercles","f":"","s":"frons tubercles; head integument","x":"pupa","d":"Cuticular surface of the pupal frons, face and thorax; bare or sparsely to densely covered with round or cone-shaped tubercles, used extensively in pupal keys (Takaoka et al. 2016, 2019, 2020; Srisuka et al. 2024).","g":"glossary.html#pupal-frons-tubercles"},"trichomes":{"t":"Trichomes","f":"","s":"frontal trichomes; facial trichomes; thoracic trichomes","x":"pupa","d":"Sensory hairs on the pupal frons, face and thorax (anterodorsal, anterolateral, mediolateral and ventrolateral); whether unbranched or branched and their relative lengths separate pupae (Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#trichomes"},"cephalic-apotome":{"t":"Cephalic apotome","f":"","s":"frontoclypeal apotome","x":"larva","d":"Dorsal sclerite of the larval head capsule bearing characteristic positive (dark) or negative (pale) head spots (anteromedial, posteromedial, mediolateral and posterolateral) used in larval keys (Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#cephalic-apotome"},"larval-antenna":{"t":"Larval antenna","f":"","s":"","x":"larva","d":"Three-segmented sensory appendage with an apical sensillum on each side of the larval head capsule; its length relative to the labral fan stem and segment proportions are recorded in larval descriptions and keys (Takaoka et al. 2016, 2020; Srisuka et al. 2024).","g":"glossary.html#larval-antenna"},"anal-sclerite":{"t":"Anal sclerite","f":"","s":"","x":"larva","d":"X-shaped dorsal sclerite on the posterior abdominal segment of the larva immediately anterior to the posterior circlet, with paired anterior and posterior arms and adjacent sensilla (Takaoka et al. 2016, 2019; Srisuka et al. 2024).","g":"glossary.html#anal-sclerite"},"a-r1":{"t":"R1","f":"radial vein 1 (first branch of radius)","d":"Anterior branch of the radial vein; bears dark spinules and hairs in <i>Simulium</i>, while presence or absence of spiniform setae on the distal R1 vein separates subgenera of <i>Austrosimulium</i> (Dumbleton 1963; Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#radial-vein","l":"Radial vein"},"a-cu2":{"t":"Cu2","f":"second cubital vein (posterior cubitus)","d":"Posterior branch of the cubital vein; straight or gently curved in <i>Cnephia</i> and <i>Gigantodax</i> versus double-curved in <i>Simulium</i> and <i>Austrosimulium</i> (Dumbleton 1963).","g":"glossary.html#a-cu2","l":""},"a-foreleg":{"t":"foreleg","f":"foreleg (prothoracic leg)","d":"First pair of legs (coxa, trochanter, femur, tibia and tarsus); fore basitarsus width and dorsal hair crest are diagnostic in females and males (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#basitarsus","l":"Basitarsus"},"a-midleg":{"t":"midleg","f":"midleg (mesothoracic leg)","d":"Second pair of legs; colour patterns of mid coxa, femur, tibia and basitarsus are used in adult keys (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#basitarsus","l":"Basitarsus"},"a-hindleg":{"t":"hind leg","f":"hind leg (metathoracic leg)","d":"Third pair of legs; bears the parallel-sided or spindle-shaped hind basitarsus with calcipala and the second tarsomere with pedisulcus (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#basitarsus","l":"Basitarsus"},"a-frontal-trichome":{"t":"frontal trichome","f":"pupal frontal trichome","d":"Paired sensory hairs (unbranched or branched) on each side of the pupal frons (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#trichomes","l":"Trichomes"},"a-facial-trichome":{"t":"facial trichome","f":"pupal facial trichome","d":"Sensory hair on each side of the pupal face, compared in length with the frontal trichomes (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#trichomes","l":"Trichomes"},"a-thoracic-trichomes":{"t":"thoracic trichomes","f":"pupal thoracic trichomes","d":"Sensory hairs on the pupal thorax (anterodorsal, anterolateral, mediolateral and ventrolateral); branching and length aid pupal identification (Takaoka et al. 2016; Srisuka et al. 2024).","g":"glossary.html#trichomes","l":"Trichomes"},"a-microtrichia":{"t":"microtrichia","f":"microtrichia of labral fan ray","d":"Row of minute hair-like projections along the posterior margin of each primary (main) ray of the larval labral fan (Srisuka et al. 2024).","g":"glossary.html#labral-fan","l":"Labral fan"},"a-anal-sensilla":{"t":"sensilla","f":"sensilla posterior to anal sclerite","d":"Row of long colourless sensilla just posterior to the basal juncture of the larval anal sclerite, anterior to the posterior circlet (Srisuka et al. 2024).","g":"glossary.html#anal-sclerite","l":"Anal sclerite"},"a-larva-body":{"t":"whole body","f":"mature larval body","d":"Whole body of the mature (final-instar) larva in dorsal and lateral views, showing abdominal pigmentation pattern and the darkened thoracic gill histoblast laterally (Srisuka et al. 2024).","g":"glossary.html#histoblast","l":"Histoblast"}};
